/// A block of code, a log or command output in monospace, with copy, folding, and an optional result of running it.
public struct CodeWidget: Decodable, Hashable, Sendable {
    /// snippet: code with line numbers and syntax colour; log: lines with times and levels; output: what a command printed.
    public var kind: Kind
    /// Syntax colour and the label on the block: swift, python, typescript, shell, json, sql, yaml, text. Not diff or patch: those go to the diff card or `diff`.
    public var language: String?
    /// kind snippet and output: the code or output as plain text with \n line breaks. A log sends `lines` instead.
    public var text: String?
    /// kind log: the lines, oldest first. The block opens at the tail.
    public var lines: [Line]?
    /// kind log: how many lines of each level the covered stretch of the log had (the title says which: “last 15 minutes”), including lines not sent. Drives the badge and the chips. Omitted: the client counts the lines it has.
    public var counts: Counts?
    /// kind log: lines before the first one sent, which the producer left out (the log parser sends the last 200). Shown as “1,840 earlier lines not sent”, with Open File when `path` is set.
    public var omitted: Int?
    /// kind log: show level chips (All · Errors · Warnings) that filter the lines on this device. Nothing is sent.
    public var filter: Bool
    /// A workspace-relative path on the gateway the code comes from or is meant for: Sync/Reconnect.swift. A tap opens it (hermes-file:) in the Inspector on iPad and Mac, Quick Look on iPhone, at `range`.
    public var path: String?
    /// The lines of `path` the snippet shows; the gutter numbers start at start. Omit for a suggestion that isn’t in the file yet (numbers start at 1).
    public var range: Range?
    /// kind output: the command that printed it, shown first after a $. Never with secrets: the plugin redacts and rejects them.
    public var command: String?
    /// The result of really running the code. Omit it when the code wasn’t run: never a guessed output.
    public var result: Outcome?

    enum CodingKeys: String, CodingKey {
        case kind
        case language
        case text
        case lines
        case counts
        case omitted
        case filter
        case path
        case range
        case command
        case result
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        kind = try container.decode(Kind.self, forKey: .kind)
        language = try container.decodeIfPresent(String.self, forKey: .language)
        text = try container.decodeIfPresent(String.self, forKey: .text)
        lines = try container.decodeIfPresent([Line].self, forKey: .lines)
        counts = try container.decodeIfPresent(Counts.self, forKey: .counts)
        omitted = try container.decodeIfPresent(Int.self, forKey: .omitted)
        filter = try container.decodeIfPresent(Bool.self, forKey: .filter) ?? true
        path = try container.decodeIfPresent(String.self, forKey: .path)
        range = try container.decodeIfPresent(Range.self, forKey: .range)
        command = try container.decodeIfPresent(String.self, forKey: .command)
        result = try container.decodeIfPresent(Outcome.self, forKey: .result)
    }

    public enum Kind: String, Decodable, Hashable, Sendable, CaseIterable {
        case snippet
        case log
        case output
    }

    public struct Line: Decodable, Hashable, Sendable {
        /// When it was written. Shown as the time of day (14:02:14) in the log’s own offset.
        public var at: String?
        /// The level, always shown as a word (INFO, WARN, ERROR). warning is orange, error and critical red; the others are secondary text. Omit when the line has none.
        public var level: Level?
        /// Which process or service wrote it, when the log mixes several: api, worker, cron.
        public var source: String?
        /// The line as written, without its time and level.
        public var text: String
        /// The same line came this many times in a row. Shown once with “×12” (a folded repeat); a tap expands it on this device.
        public var `repeat`: Int?

        enum CodingKeys: String, CodingKey {
            case at
            case level
            case source
            case text
            case `repeat`
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            at = try container.decodeIfPresent(String.self, forKey: .at)
            level = try container.decodeIfPresent(Level.self, forKey: .level)
            source = try container.decodeIfPresent(String.self, forKey: .source)
            text = try container.decode(String.self, forKey: .text)
            `repeat` = try container.decodeIfPresent(Int.self, forKey: .repeat)
        }

        public enum Level: String, Decodable, Hashable, Sendable, CaseIterable {
            case trace
            case debug
            case info
            case notice
            case warning
            case error
            case critical
        }
    }

    public struct Counts: Decodable, Hashable, Sendable {
        public var error: Int?
        public var warning: Int?
        public var info: Int?
        public var debug: Int?

        enum CodingKeys: String, CodingKey {
            case error
            case warning
            case info
            case debug
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            error = try container.decodeIfPresent(Int.self, forKey: .error)
            warning = try container.decodeIfPresent(Int.self, forKey: .warning)
            info = try container.decodeIfPresent(Int.self, forKey: .info)
