            case start
            case end
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            start = try container.decode(Int.self, forKey: .start)
            end = try container.decodeIfPresent(Int.self, forKey: .end)
        }
    }

    public struct Outcome: Decodable, Hashable, Sendable {
        /// ok: it ran and did what was expected (exit 0); warning: it ran, with warnings; critical: it failed or threw. Drawn as the state glyph before the label.
        public var state: State
        /// The result line: “Ran in 0.4 s”, “Failed · exit 1 · 12.4 s”. The client builds it from exit_code and duration when it’s omitted.
        public var label: String?
        /// The process exit code, when there is one.
        public var exitCode: Int?
        /// How long it ran.
        public var duration: Double?
        /// What it printed or returned, shown after the label in monospace: “0.25 0.5 1 2 4 5”. Longer output is its own code widget with kind output.
        public var output: String?
        public var ranAt: String?
        /// Where it ran, when that matters: “on Studio Mac”, “in a sandbox”.
        public var `where`: String?

        enum CodingKeys: String, CodingKey {
            case state
            case label
            case exitCode = "exit_code"
            case duration
            case output
            case ranAt = "ran_at"
            case `where`
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            state = try container.decode(State.self, forKey: .state)
