/// Progress through ordered stages — waiting, running (with its own progress), done, failed, skipped, blocked, unknown — with durations and a result line.
public struct StepsWidget: Decodable, Hashable, Sendable {
    /// The stages, in order.
    public var steps: [Step]
    /// vertical: one row per step. pipeline: 2–6 stages as chips in a row. compact: one line and a segmented bar.
    public var kind: Kind
    /// The outcome in one line, under the steps. Required in a pipeline that failed.
    public var result: Outcome?
    /// When the job started; the footer says “Started 10:02 by <producer>”.
    public var startedAt: String?

    enum CodingKeys: String, CodingKey {
        case steps
        case kind
        case result
        case startedAt = "started_at"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        steps = try container.decode([Step].self, forKey: .steps)
        kind = try container.decodeIfPresent(Kind.self, forKey: .kind) ?? .vertical
        result = try container.decodeIfPresent(Outcome.self, forKey: .result)
        startedAt = try container.decodeIfPresent(String.self, forKey: .startedAt)
    }

    public struct Step: Decodable, Hashable, Sendable {
        public var id: String
        /// The stage, as a short action or noun: “Install dependencies”, “Test”, “Customs”. ≤ 16 characters in a pipeline.
        public var title: String
        /// The shared progress vocabulary (also `outline`). waiting (hollow circle: not started), running (ink ring, bold), done (green check), failed (red ✕), skipped (grey dash), blocked (orange hand: can’t go on until someone acts; `detail` says what it waits for), unknown (dashed question mark: nobody knows the outcome; `detail` says the last thing known).
        public var state: State
        /// One line under the title: “about 2 min left”, “npm ERR! 404 @trailhead/ui”, “Import duty of $12.40 to pay”, “No report since 10:14”. Required for blocked and unknown.
        public var detail: String?
        /// How long the step took (done, failed). Leave it out for steps that haven’t finished.
        public var duration: Double?
        /// For the running step: 0–1. Leave it out when unknown: the client draws an indeterminate bar, never a guessed percentage.
        public var progress: Double?
        /// How the outcome is known: the test report, the log, the tracking page. A claim reads “Said by …” and the step is never shown as checked on a claim alone.
        public var evidence: WidgetEvidence?
        /// Row actions (“Retry”, “Show the Log”); they send their id with `{item: <step id>}`.
        public var actions: [WidgetAction]?

        enum CodingKeys: String, CodingKey {
            case id
            case title
            case state
            case detail
            case duration
            case progress
            case evidence
            case actions
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = try container.decode(String.self, forKey: .id)
            title = try container.decode(String.self, forKey: .title)
            state = try container.decode(State.self, forKey: .state)
            detail = try container.decodeIfPresent(String.self, forKey: .detail)
            duration = try container.decodeIfPresent(Double.self, forKey: .duration)
            progress = try container.decodeIfPresent(Double.self, forKey: .progress)
            evidence = try container.decodeIfPresent(WidgetEvidence.self, forKey: .evidence)
            actions = try container.decodeIfPresent([WidgetAction].self, forKey: .actions)
        }

        public enum State: String, Decodable, Hashable, Sendable, CaseIterable {
            case waiting
            case running
            case done
            case failed
            case skipped
            case blocked
            case unknown
        }
    }

    public enum Kind: String, Decodable, Hashable, Sendable, CaseIterable {
        case vertical
        case pipeline
        case compact
    }

    public struct Outcome: Decodable, Hashable, Sendable {
        public var state: State
        /// One sentence: what failed, or what came out.
        public var text: String
        /// The specifics: failing test names, the error.
        public var detail: String?
        /// code sets the detail in mono.
        public var detailStyle: DetailStyle

        enum CodingKeys: String, CodingKey {
            case state
            case text
            case detail
            case detailStyle = "detail_style"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            state = try container.decode(State.self, forKey: .state)
            text = try container.decode(String.self, forKey: .text)
            detail = try container.decodeIfPresent(String.self, forKey: .detail)
            detailStyle = try container.decodeIfPresent(DetailStyle.self, forKey: .detailStyle) ?? .text
        }

        public enum State: String, Decodable, Hashable, Sendable, CaseIterable {
            case ok
            case info
            case warning
            case critical
            case unverified
        }

        public enum DetailStyle: String, Decodable, Hashable, Sendable, CaseIterable {
            case text
            case code
        }
    }
}

