/// One question with set answers — a list, buttons, chips, a rating, times to pick, or several to tick — answered with one tap; plus suggested follow-ups the person can send as their own words.
public struct ChoiceWidget: Decodable, Hashable, Sendable {
    /// The question, as the agent would ask it: “Which flight should I book for Tuesday?” Required for every style except suggestions.
    public var question: String?
    /// How the options are drawn. buttons falls back to list with more than 3 options or a label over 24 characters; chips falls back to list over 24 characters.
    public var style: Style
    /// one: a tap answers at once. many: checkboxes and a Send button (list and chips only).
    public var select: Select
    /// style: rating only. stars and scale take 5 options, thumbs 2, from low to high.
    public var rating: Rating
    /// The answers, in the order to show them.
    public var options: [Option]
    /// Adds a one-line Other field (list, chips). With select: one, typing in it shows Send.
    public var other: Other?
    /// A way out under the options, as a text button: “None of these work”. Sends `answer` with `selected: []`.
    public var declineLabel: String?
    /// One quiet line under the options: “Something else? Just reply in the chat.”
    public var note: String?
    /// The answer as the agent received it, set in the update together with `resolution`, so every device draws the answered state.
    public var answer: Answer?

    enum CodingKeys: String, CodingKey {
        case question
        case style
        case select
        case rating
        case options
        case other
        case declineLabel = "decline_label"
        case note
        case answer
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        question = try container.decodeIfPresent(String.self, forKey: .question)
        style = try container.decodeIfPresent(Style.self, forKey: .style) ?? .list
        select = try container.decodeIfPresent(Select.self, forKey: .select) ?? .one
        rating = try container.decodeIfPresent(Rating.self, forKey: .rating) ?? .stars
        options = try container.decode([Option].self, forKey: .options)
        other = try container.decodeIfPresent(Other.self, forKey: .other)
        declineLabel = try container.decodeIfPresent(String.self, forKey: .declineLabel)
        note = try container.decodeIfPresent(String.self, forKey: .note)
        answer = try container.decodeIfPresent(Answer.self, forKey: .answer)
    }

    public enum Style: String, Decodable, Hashable, Sendable, CaseIterable {
        case list
        case buttons
        case chips
        case rating
        case times
        case suggestions
    }

    public enum Select: String, Decodable, Hashable, Sendable, CaseIterable {
        case one
        case many
    }

    public enum Rating: String, Decodable, Hashable, Sendable, CaseIterable {
        case stars
        case thumbs
        case scale
    }

    public struct Option: Decodable, Hashable, Sendable {
        public var id: String
        /// What the person picks. Buttons and chips ≤ 24 characters (longer labels make the client draw a list). Times: the full slot in words (“Sat, Oct 17, 11:30 AM”). Rating: the meaning of that point (“Very useful”). Suggestions: the exact message sent as the person’s own (≤ 80).
        public var label: String
        /// One line under the label (list and multi): “Nonstop · $286 · lands in time for check-in”. Unknown is said in words (“price not known yet”).
        public var detail: String?
        /// The one suggested answer: a “Recommended” tag in a list, the ink chip or button. At most one; never preselected in select: one.
        public var recommended: Bool
        /// select: many only: ticked before the person changes anything. A plan to approve step by step preselects every step.
        public var preselected: Bool
        /// style: times only: the slot’s start. The client groups slots by day in the reader’s time zone, shows the time, and disables slots already past.
        public var at: String?

        enum CodingKeys: String, CodingKey {
            case id
            case label
            case detail
            case recommended
            case preselected
            case at
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = try container.decode(String.self, forKey: .id)
            label = try container.decode(String.self, forKey: .label)
            detail = try container.decodeIfPresent(String.self, forKey: .detail)
            recommended = try container.decodeIfPresent(Bool.self, forKey: .recommended) ?? false
            preselected = try container.decodeIfPresent(Bool.self, forKey: .preselected) ?? false
            at = try container.decodeIfPresent(String.self, forKey: .at)
        }
    }

    public struct Other: Decodable, Hashable, Sendable {
        /// The field’s placeholder: “Other…”, “Another app”.
        public var placeholder: String?

        enum CodingKeys: String, CodingKey {
            case placeholder
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            placeholder = try container.decodeIfPresent(String.self, forKey: .placeholder)
        }
    }

    public struct Answer: Decodable, Hashable, Sendable {
        /// The option ids chosen.
        public var selected: [String]
        /// What the person wrote in Other.
        public var other: String?

        enum CodingKeys: String, CodingKey {
            case selected
            case other
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            selected = try container.decode([String].self, forKey: .selected)
            other = try container.decodeIfPresent(String.self, forKey: .other)
        }
    }
}

/// A few things the agent needs filled in — text, numbers, dates, times, a menu, a switch — prefilled where it can, sent in one go.
public struct FormWidget: Decodable, Hashable, Sendable {
    /// One line under the header: why the agent asks.
    public var intro: String?
    /// The inputs, in order.
    public var fields: [Field]
    /// The Send button’s verb: Send, Search, Add Expense.
    public var submitLabel: String
    /// The values as the agent received them (field id → value), set in the update together with `resolution`, so every device draws the sent state.
    public var submitted: [String: WidgetValue]?

    enum CodingKeys: String, CodingKey {
        case intro
        case fields
        case submitLabel = "submit_label"
        case submitted
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        intro = try container.decodeIfPresent(String.self, forKey: .intro)
        fields = try container.decode([Field].self, forKey: .fields)
        submitLabel = try container.decodeIfPresent(String.self, forKey: .submitLabel) ?? "Send"
        submitted = try container.decodeIfPresent([String: WidgetValue].self, forKey: .submitted)
    }

    public struct Field: Decodable, Hashable, Sendable {
        public var id: String
        /// The input. There is no password or secret kind: Hermes asks for secrets with its own secure request.
        public var kind: Kind
        /// A noun phrase: “Who’s coming”, “Arrive”, “Budget per night”.
        public var label: String
        /// An example in grey, never an instruction the person must read: “Near the lake, with parking”.
        public var placeholder: String?
        /// Marked with a red asterisk; Send stays off until it’s filled.
        public var required: Bool
        /// Prefilled value, so the person confirms rather than types: text; a number; date 2026-10-31; time 12:30; datetime RFC 3339; an option id for choice; true / false for toggle.
        public var `default`: WidgetValue?
        /// kind choice: a menu (2–12 options).
        public var options: [Option]?
        /// number: the lowest value; date, time, datetime: the earliest.
        public var min: WidgetValue?
        /// number: the highest value; date, time, datetime: the latest.
        public var max: WidgetValue?
        /// text and long_text: at most this many characters (default 200 and 2,000).
        public var maxLength: Int?
        /// kind number: shown after the value: nights, kg, people.
        public var unit: String?
        /// kind number: ISO 4217 code; the field formats money.
        public var currency: String?
        /// One line under the field.
        public var help: String?

        enum CodingKeys: String, CodingKey {
            case id
            case kind
            case label
            case placeholder
            case required
            case `default`
            case options
            case min
            case max
            case maxLength = "max_length"
            case unit
