        undo = try container.decodeIfPresent(Undo.self, forKey: .undo)
        undone = try container.decodeIfPresent(Undone.self, forKey: .undone)
        note = try container.decodeIfPresent(String.self, forKey: .note)
        confirmation = try container.decode(WidgetEvidence.self, forKey: .confirmation)
