/// Two to four options side by side on the same criteria, the recommended one outlined in ink, and what decided it in one sentence; the weights can be the person’s own.
public struct CompareWidget: Decodable, Hashable, Sendable {
    /// The options, in the order the agent ranks them or the order the person named them. 2–4.
    public var options: [Option]
    /// The rows, most important first. Optional only for a cards comparison where every option has pros or cons.
    public var criteria: [Criterion]?
    /// The recommended option’s id: outlined in ink with a Pick badge. Omit when there is no clear winner (nothing is outlined). With `adjustable`, it must be the option with the highest weighted score at the sent weights.
    public var pick: String?
    /// One sentence on what decided it, written to follow the option’s name and a colon (the client puts the name in front, in bold): “the same noise cancelling for less, with twice the battery. Battery decided it.” Required with `pick`; without one, what the choice hinges on, as a full sentence.
    public var decidedBy: String?
    /// auto: the grid on the iPhone column; cards on a wide column (≥ 560 pt) when every option has pros or cons, else the grid. `adjustable` always draws the grid.
    public var layout: Layout
    /// The person can change each criterion’s weight on the device (0–5). Scores re-rank locally, the outline and the Go with button follow the top score, and Reset Weights restores the sent weights. Needs at least one criterion with `weight` and `scores`.
    public var adjustable: Bool
    /// Show Go with <the top option> as the primary button. It sends `answer`. Use when the agent will act on the choice (book it, order it, draft the purchase for approval).
    public var choose: Bool

    enum CodingKeys: String, CodingKey {
        case options
        case criteria
        case pick
        case decidedBy = "decided_by"
        case layout
        case adjustable
        case choose
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        options = try container.decode([Option].self, forKey: .options)
        criteria = try container.decodeIfPresent([Criterion].self, forKey: .criteria)
        pick = try container.decodeIfPresent(String.self, forKey: .pick)
        decidedBy = try container.decodeIfPresent(String.self, forKey: .decidedBy)
        layout = try container.decodeIfPresent(Layout.self, forKey: .layout) ?? .auto
        adjustable = try container.decodeIfPresent(Bool.self, forKey: .adjustable) ?? false
        choose = try container.decodeIfPresent(Bool.self, forKey: .choose) ?? false
    }

    public struct Option: Decodable, Hashable, Sendable {
        public var id: String
        /// The option as people say it: “Sony XM6”, “DigitalOcean Droplet”, “Apartment in Gowanus”. The column header in the grid, the card title on cards.
        public var name: String
        /// A product shot or photo. Grid: a 44 pt thumbnail above the name, drawn only when every option has one. Cards: the top of the card. Fetched by the gateway like every remote image.
        public var image: WidgetMedia?
        /// The headline price: large under the name on cards, and in the fallback. The grid shows price only as a criterion (so it can carry a weight); repeat it there when it should be a row.
        public var price: WidgetQuantity?
        /// Up to four plus points, a few words each: “40 h battery”, “Folds flat”. Drawn on cards after a plus glyph.
        public var pros: [String]?
        /// Up to four minus points: “Plasticky”, “24 h battery”. Drawn on cards after a minus glyph (shape, never colour alone).
        public var cons: [String]?
        /// The product or listing page, opened from the link glyph after the name (the domain shows first).
        public var url: String?

        enum CodingKeys: String, CodingKey {
            case id
            case name
            case image
            case price
            case pros
            case cons
            case url
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = try container.decode(String.self, forKey: .id)
            name = try container.decode(String.self, forKey: .name)
            image = try container.decodeIfPresent(WidgetMedia.self, forKey: .image)
            price = try container.decodeIfPresent(WidgetQuantity.self, forKey: .price)
            pros = try container.decodeIfPresent([String].self, forKey: .pros)
            cons = try container.decodeIfPresent([String].self, forKey: .cons)
            url = try container.decodeIfPresent(String.self, forKey: .url)
        }
    }

    public struct Criterion: Decodable, Hashable, Sendable {
        public var id: String
        /// What is compared: Price, Battery, Noise cancelling, Commute to work.
        public var label: String
        /// The value for each option, keyed by option id: a Quantity (formatted by the client, tabular figures) or a word. Every option needs a key; an unknown value is `{"value": null}` (shown as —, read as “unknown”), never a guess.
        public var values: [String: WidgetFieldValue]
        /// The options that win on this criterion. Their value is semibold and read as “best”. Omit when nothing stands out or it is a matter of taste.
        public var best: [String]?
        /// How much the criterion counts, 0–5 (0: shown, not counted). Needs `scores`. With `adjustable`, the starting value of the stepper.
        public var weight: Int?
        /// A score from 1 to 5 for each option on this criterion (5 is best), keyed by option id. Needs `weight`. The client needs a score for every option; an option the agent can’t score means the criterion gets no weight.
        public var scores: [String: Int]?
        /// How the values are known: “rtings.com battery test, Sept 2026”. A caption under the label with a small glyph; a `claim` (“Sony says 40 h”) reads “Said by …”.
        public var evidence: WidgetEvidence?

        enum CodingKeys: String, CodingKey {
            case id
            case label
            case values
            case best
            case weight
            case scores
            case evidence
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = try container.decode(String.self, forKey: .id)
            label = try container.decode(String.self, forKey: .label)
            values = try container.decode([String: WidgetFieldValue].self, forKey: .values)
            best = try container.decodeIfPresent([String].self, forKey: .best)
            weight = try container.decodeIfPresent(Int.self, forKey: .weight)
            scores = try container.decodeIfPresent([String: Int].self, forKey: .scores)
            evidence = try container.decodeIfPresent(WidgetEvidence.self, forKey: .evidence)
        }
    }

    public enum Layout: String, Decodable, Hashable, Sendable, CaseIterable {
        case auto
        case grid
        case cards
    }
}

/// Who handed what to whom and how it’s going: one Bot asks another (or a person) to do part of the work, and the result comes back here.
public struct HandoffWidget: Decodable, Hashable, Sendable {
    /// Who handed it over: usually the producer (Hermes or a Bot, with `bot` set).
    public var from: WidgetPerson
    /// Who took it: one of the person’s Bots (`bot` set: its face and its chat) or a person (initials; no chat link).
    public var to: WidgetPerson
    /// The work.
    public var task: Job
    /// Where the handoff is. done needs a result; declined needs a reason.
    public var status: Status
    /// Where to follow the work. Only for a Bot on the same gateway: the schema requires `to.bot` with it.
    public var chat: Chat?
    /// When it was handed over.
    public var sentAt: String?

    enum CodingKeys: String, CodingKey {
        case from
        case to
        case task
        case status
        case chat
        case sentAt = "sent_at"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        from = try container.decode(WidgetPerson.self, forKey: .from)
        to = try container.decode(WidgetPerson.self, forKey: .to)
        task = try container.decode(Job.self, forKey: .task)
        status = try container.decode(Status.self, forKey: .status)
        chat = try container.decodeIfPresent(Chat.self, forKey: .chat)
        sentAt = try container.decodeIfPresent(String.self, forKey: .sentAt)
    }

    public struct Job: Decodable, Hashable, Sendable {
        /// What was handed over, as the line after “Hermes asked Ada”: “to draft the 1.3 release notes”.
        public var title: String
        /// The brief the other side received, quoted as sent: what to do and any limits (“Check with the user before publishing.”).
        public var context: String?

        enum CodingKeys: String, CodingKey {
            case title
            case context
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            title = try container.decode(String.self, forKey: .title)
            context = try container.decodeIfPresent(String.self, forKey: .context)
        }
    }

    public struct Status: Decodable, Hashable, Sendable {
        /// sent: handed over, not picked up yet (hourglass). accepted: the other Bot took it. working: it is on it (waving dots and the activity). done: finished, with a result (green check). declined: it said no, with the reason (orange triangle).
        public var state: State
        /// What the other side is doing now, in the app’s activity words, without its name: “is writing”, “is running the tests”, “is waiting for you”. The client puts the name in front.
        public var activity: String?
        /// Progress so far, when it can be counted: 2 (of 4 sections).
        public var done: Int?
        /// Out of: 4.
        public var total: Int?
        /// What is counted: sections, files, listings.
        public var unit: String?
        /// When it entered this state: “Accepted 09:14”, “Finished 10:02”.
        public var since: String?
        /// What the other side produced.
        public var result: Outcome?
        /// Why it was declined, in the other side’s words: “No SSH access to the NAS from this gateway”.
        public var reason: String?

        enum CodingKeys: String, CodingKey {
            case state
            case activity
            case done
            case total
            case unit
            case since
            case result
            case reason
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            state = try container.decode(State.self, forKey: .state)
            activity = try container.decodeIfPresent(String.self, forKey: .activity)
            done = try container.decodeIfPresent(Int.self, forKey: .done)
            total = try container.decodeIfPresent(Int.self, forKey: .total)
            unit = try container.decodeIfPresent(String.self, forKey: .unit)
            since = try container.decodeIfPresent(String.self, forKey: .since)
            result = try container.decodeIfPresent(Outcome.self, forKey: .result)
            reason = try container.decodeIfPresent(String.self, forKey: .reason)
        }

        public enum State: String, Decodable, Hashable, Sendable, CaseIterable {
            case sent
            case accepted
            case working
            case done
            case declined
        }

        public struct Outcome: Decodable, Hashable, Sendable {
            /// What came back, one line: “Release notes for 1.3 · 412 words · 3 sections”.
            public var summary: String
            /// Where the result is: a gateway file (`hermes-file:`, opened in the Inspector on iPad and Mac, Quick Look on iPhone) or a page.
            public var url: String?
            /// The button that opens it: Read the Draft, Open the Report, See the Fix. Defaults to Open.
            public var label: String?
            /// A preview when the result is visual: a chart, a mock-up, a photo.
            public var media: WidgetMedia?

            enum CodingKeys: String, CodingKey {
                case summary
                case url
                case label
                case media
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                summary = try container.decode(String.self, forKey: .summary)
                url = try container.decodeIfPresent(String.self, forKey: .url)
                label = try container.decodeIfPresent(String.self, forKey: .label)
                media = try container.decodeIfPresent(WidgetMedia.self, forKey: .media)
            }
        }
    }

    public struct Chat: Decodable, Hashable, Sendable {
        /// The gateway session id of the chat where the other Bot does the work. The client draws Open <Bot>’s Chat from it.
        public var session: String

        enum CodingKeys: String, CodingKey {
            case session
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            session = try container.decode(String.self, forKey: .session)
        }
    }
}

