    static func decode(_ type: WidgetType, from decoder: any Decoder) throws -> WidgetContent {
        switch type {
        case .metric: .metric(try MetricWidget(from: decoder))
        case .meter: .meter(try MeterWidget(from: decoder))
        case .chart: .chart(try ChartWidget(from: decoder))
